+    String LIST_FILTER = """
+            WHERE (:allCategories = true
+                OR (:uncategorized = true AND d.category_id IS NULL)
+                OR (:uncategorized = false AND d.category_id = :categoryId))
+              AND (:pattern = '' OR LOWER(d.title) LIKE :pattern ESCAPE '!'
